 * Longest common subsequence matching between a base document and one side,
 * comparing whole lines as exact strings.
 *
 * When several subsequences of maximal length exist, the one whose matches
 * come earliest is chosen: walking both documents from the start, a match is
 * taken whenever the current lines are equal; otherwise the side whose
 * remaining subsequence (after advancing) is at least as long as the other's
 * is advanced, with the base preferred on a tie.
 */

/**
 * @param {string[]} base
 * @param {string[]} side
 * @returns {Array<[number, number]>} pairs of [baseIndex, sideIndex] for each
 *   matched line, in increasing order of both indices.
 */
export function lcsMatches(base, side) {
  const n = base.length
  const m = side.length
  // dp[i][j] = length of the LCS of base[i:] and side[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}
"}

